use verus::prelude::*;

verus! {

    // Given an 8-bit signed integer n > 1, returns its largest proper divisor d.
    // Ensures: 1 ≤ d < n, n % d == 0,
    // and no k with d < k < n divides n.
    pub fn largest_divisor(n: i8) -> i8
        requires n > 1
        ensures |d: i8|  1 <= d && d < n
        ensures |d: i8|  n % d == 0
        ensures |d: i8|  forall |k: i8| (d < k && k < n) ==> n % k != 0
    {
        // d will track the largest divisor found so far
        let mut d: i8 = 1;
        // k scans from 1 up to n-1
        let mut k: i8 = 1;

        // Loop until k == n.  At each step we maintain:
        //  1 <= d < n
        //  1 <= k <= n
        //  d divides n
        //  and among all t with 1 <= t < k that divide n, t <= d
        while k < n
            invariant 1 <= d && d < n
            invariant 1 <= k && k <= n
            invariant n % d == 0
            invariant forall |t: i8| (1 <= t && t < k && n % t == 0) ==> t <= d
            // measure is (n - k) as u8, which decreases each iteration
            decreases (n - k) as u8
        {
            if n % k == 0 {
                // k is a proper divisor ⇒ record it if it's the largest so far
                d = k;
            }
            k += 1;
        }

        // At exit, k == n, so by the invariant
        //  for all t with 1 <= t < n, if t divides n then t <= d.
        // Hence d is the maximal proper divisor.
        d
    }

}